                    "sql": "Create or replace table maplemonk.CC_PANDL as Select customer_id_final, acquisition_date, first_complete_order_date, Order_Quantity, maple_monk_id_phone, coalesce(sc.region,mc_ppc.region) as region, delivery_country, customer_id, Business_Segment, coalesce(sc.brand,mc_ppc.brand) as brand, Shop_name, upper(coalesce(marketplace , case when lower(coalesce(sc.CHANNEL,mc_ppc.channel)) like \'%amazon%\' then \'AMAZON\' when lower(coalesce(sc.CHANNEL,mc_ppc.channel)) is not null then \'WEBSITE\' end )) marketplace, coalesce(sc.CHANNEL,mc_ppc.channel) as Channel, SOURCE, order_id, reference_code, phone, name, email, SHIPPING_LAST_UPDATE_DATE, sku, product_id, product_name, CURRENCY, City, State, Order_Status, coalesce(order_date,mc_ppc.date) as Order_date, Order_Time, quantity, GROSS_SALES_BEFORE_TAX, DISCOUNT, TAX, SHIPPING_PRICE, SELLING_PRICE, OMS_order_status, SHIPPING_STATUS, FINAL_SHIPPING_STATUS, SALEORDERITEMCODE, SALES_ORDER_ITEM_ID, AWB, Payment_Gateway, Payment_Mode, COURIER, DISPATCH_DATE, paid_date, DELIVERED_DATE, DELIVERED_STATUS, RETURN_FLAG, returned_quantity, returned_sales, cancelled_quantity, Days_in_Shipment, SKU_CODE, PRODUCT_NAME_FINAL, PRODUCT_CATEGORY, PRODUCT_SUB_CATEGORY, commonsku, WAREHOUSE, pincode, source_pincode, discount_codes, Return_date, new_customer_flag, new_customer_flag_month, acquisition_product, acquisition_channel, acquisition_marketplace, Product_Cost, Product_Other_Cost, safe_divide(selling_price , SUM(selling_price) OVER (PARTITION BY sc.order_id)) as Percent, safe_divide(selling_price , SUM(selling_price) OVER (PARTITION BY sc.order_id)) * ifnull(Refund_Amount,0) as Refund_Amount, safe_divide(selling_price , SUM(selling_price) OVER (PARTITION BY sc.order_id)) * ifnull(amazon_comm,0) as amazon_comm, safe_divide(selling_price , SUM(selling_price) OVER (PARTITION BY sc.order_id)) * ifnull(chargeback_amount,0) as chargeback_amount, safe_divide(selling_price , SUM(selling_price) OVER (PARTITION BY sc.order_id)) * ifnull(storage_fee,0) as storage_fee, safe_divide(selling_price , SUM(selling_price) OVER (PARTITION BY sc.order_id)) * ifnull(Outbound_Charges,0) as Outbound_Charges, safe_divide(selling_price , SUM(selling_price) OVER (PARTITION BY sc.order_id)) * ifnull(removal_charges,0) as removal_charges, safe_divide(selling_price , SUM(selling_price) OVER (PARTITION BY sc.order_id)) * ifnull(Affiliation_Cost,0) as Affiliation_Cost, safe_divide(ifnull(Spend,0) , count(*) OVER (PARTITION BY coalesce(order_date,mc_ppc.date) ,lower(coalesce(sc.CHANNEL,mc_ppc.channel)) ,lower(coalesce(sc.region,mc_ppc.region)) ,lower(coalesce(sc.region,mc_ppc.region)) )) as Spend, from MAPLEMONK.CC_sales_consolidated SC left join ( select opr_order_id ,sum(ifnull(opr_refund_amount,0)) Refund_Amount from cc_comfort_db.order_partial_refund group by 1 ) rf on lower(cast(rf.opr_order_id as string)) = lower(cast(sc.order_id as string)) left join ( select order_id as op_order_id ,sum(ifnull(amazon_comm,0)) amazon_comm ,sum(ifnull(chargeback_amount,0)) as chargeback_amount ,sum(ifnull(storage_fee,0)) storage_fee ,sum(ifnull(postage_fee,0)) Outbound_Charges ,sum(ifnull(removal_charges,0)) removal_charges from cc_comfort_db.order_processing group by 1 )op on lower(cast(op.op_order_id as string)) = lower(cast(sc.order_id as string)) left join ( Select Order_id af_order_id, Sum(ifnull(order_commission ,0)) + sum(ifnull(network_cost,0)) as Affiliation_Cost from cc_comfort_db.affiliates_network_sales_track_data where lower(order_status) = \'approved\' group by 1 )af on lower(cast(af.af_order_id as string)) = lower(cast(sc.order_id as string)) full outer join ( select channel ,date ,region ,brand ,sum(ifnull(spend,0)) Spend from `MAPLEMONK.CC_MARKETING_CONSOLIDATED` group by 1,2,3,4 )mc_ppc on cast(mc_ppc.date as date) = cast(sc.order_date as date) and lower(mc_ppc.channel) = lower(sc.channel) and lower(mc_ppc.region) = lower(sc.region) and lower(mc_ppc.brand) = lower(sc.brand) ;",
